-- Class notes synopsis batch 25: Tea (Green Tea) through Velvet Bean

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Tea</strong> (Green Tea, Camellia sinensis) is an <strong>antioxidant</strong>, <strong>astringent</strong>, and <strong>5-alpha reductase inhibitor</strong>. Inhibits 5-alpha reductase to reduce DHT in hormone-sensitive prostate tissue; for <strong>BPH</strong>: part of formula with <a href="?herb=186"><strong>Saw Palmetto</strong></a>, <a href="?herb=1649"><strong>Nettle Root</strong></a>, <a href="?herb=203"><strong>Turmeric</strong></a>, <a href="?herb=11"><strong>Reishi Mushroom</strong></a>, and Panax ginseng. Antioxidant to reduce free radicals and oxidation in the body. <strong>Wound wash</strong>: astringent. <strong>Caution: caffeine sensitivity may cause a stress response and blood sugar spike — consider the individual's caffeine tolerance.</strong>$$
WHERE id = 149;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Tea Tree</strong> is an <strong>antimicrobial</strong> herb used in wound wash preparations. Covers gram-negative bacteria (E. coli); paired with <a href="?herb=82"><strong>Lavender</strong></a> in wet wipes and wound washes (lavender covers gram-positive bacteria: staph and MRSA, sidestepping antibiotic resistance). Combined with culinary antimicrobials (<a href="?herb=59"><strong>Thyme</strong></a>, Rosemary, Oregano) and <a href="?herb=44"><strong>Yarrow</strong></a> in wound wash formulas.$$
WHERE id = 302;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Thuja</strong> (White Cedar, Thuja occidentalis) is an <strong>antimicrobial</strong>, <strong>lymphatic</strong>, and <strong>urogenital</strong> herb with deep roots in African American and Native American herbal traditions — documented among 108 species in the African American Materia Medica. For <strong>wound wash</strong>: antimicrobial. Native Americans used for fevers, coughs, headaches, swollen hands, and rheumatic problems. <strong>Skin</strong>: warts, oily and dry skin eruptions, nail fungus, hemorrhoids. <strong>Urogenital</strong>: swollen or inflamed urethra, weak urine stream, frequent urge to urinate, urinary infections, STD/gonorrhea. <strong>Tick bites</strong>: apply Thuja EO to the tick site after careful removal — "some say this can stop Lyme"; recommended for first aid kit. <strong>Lymph/immune deficiency</strong>: supports acquired immune function. Preparation: infusion, steam/inhalation, external wash; extraction 1:2 in 50% alcohol.$$
WHERE id = 201;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Thyme</strong> is a <strong>warming</strong>, <strong>pungent</strong>, <strong>antimicrobial</strong>, and <strong>antitussive</strong> herb with an affinity for the thymus. For <strong>respiratory</strong>: steam for opening up the lungs; herb for bronchitis with antispasmodic, expectorant, and anti-catarrhal properties; antitussive for asthma; used in pine and eucalyptus inhalations for congestion. For <strong>urinary</strong>: urinary antiseptic that kills bacteria in the urinary tract. For <strong>wounds</strong>: antimicrobial in wound wash alongside Tea Tree, <a href="?herb=109"><strong>Rosemary</strong></a>, Oregano, and <a href="?herb=44"><strong>Yarrow</strong></a>. Inhibits H. pylori (peptic ulcer). Mixes well with <a href="?herb=54"><strong>Elecampane</strong></a>; excellent as thyme honey. Used in Four Thieves Vinegar and antimicrobial oxymel. Herbal salt ingredient.$$
WHERE id = 59;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Trillium</strong> is a <strong>cooling</strong> herb indicated for <strong>reproductive excess</strong>; cools the system in both female and male reproductive excess conditions.$$
WHERE id = 2626;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Turkey Corn</strong> (Bleeding Heart, Dicentra eximia) is energetically supportive of <strong>grief</strong>; referenced in Michael Moore's Materia Medica. Part of a tonic tincture for grief support alongside <a href="?herb=1652"><strong>Hawthorn</strong></a> and <a href="?herb=2746"><strong>Mimosa</strong></a> (Silk Tree).$$
WHERE id = 2612;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Turmeric</strong> (Curcuma longa) is a <strong>warming</strong>, <strong>anti-inflammatory</strong>, <strong>antioxidant</strong>, <strong>cholagogue</strong> (predominantly choleretic), and <strong>hepatoprotective</strong> herb — used in Ayurvedic medicine from approximately 1000 BCE. For <strong>liver and biliary</strong>: increases bile production; good for gallstones and biliary pain (safer than strong cholagogues for patients with gallstone risk); improves liver enzymes; for metabolic-associated fatty liver disease (MAFLD) alongside <a href="?herb=33"><strong>Oregon Grape Root</strong></a>; hepatoprotective against hepatitis damage; promotes Phase 2 detox; hepatic for hot constitution alongside <a href="?herb=206"><strong>Milk Thistle</strong></a> and <a href="?herb=172"><strong>Artichoke</strong></a> leaf. For <strong>inflammation</strong>: go-to anti-inflammatory for rheumatoid arthritis, endometriosis, and PMOS; suppresses reactive oxygen species (free radicals); reduces LDL and decreases platelet aggregation; inhibits pancreatic fibrosis; anti-inflammatory for psoriasis; "Curamed" by Terry's Naturals (concentrated extract with Frankincense) for powerful anti-inflammatory support. For <strong>digestion</strong>: warming bitter for hypochlorhydria; inhibits H. pylori; heals gastric mucosa (peptic ulcer); GI alterative. For <strong>BPH and prostate</strong>: inhibits 5-alpha reductase to reduce DHT alongside <a href="?herb=186"><strong>Saw Palmetto</strong></a>, green tea, <a href="?herb=1649"><strong>Nettle Root</strong></a>, and <a href="?herb=11"><strong>Reishi Mushroom</strong></a>. For <strong>metabolic syndrome</strong>: with <a href="?herb=2747"><strong>Nigella</strong></a> (Black Seed) for unhealthy blood lipids. For <strong>fibroids</strong>: combined with <a href="?herb=2238"><strong>White Peony</strong></a>. For <strong>cancer support</strong>: cell signaling, apoptosis, anti-inflammatory. <strong>Dosage</strong>: capsules 500mg 2–4x/day; golden milk 1–2 tsp 5x/day (1T in kitcheree, 1/2 tsp in 1 cup golden milk); or simmer with <a href="?herb=124"><strong>Ginger</strong></a> and <a href="?herb=2498"><strong>Black Pepper</strong></a> 10 min, steep 10 min twice daily; absorption enhanced by black pepper and fat. "Excellent daily tonic when waste has built up with generalized pain — prefer golden milk or food."$$
WHERE id = 203;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Usnea</strong> (a lichen) is "one of the strongest antimicrobials we have" — an <strong>antimicrobial</strong>, <strong>antifungal</strong>, and <strong>immune</strong> herb with primary <strong>urinary affinity</strong>; safe for use in pregnancy and children. <strong>Identification</strong>: a white thread inside when pulled (Spanish moss just breaks); a sage-y smell usually indicates antimicrobial action. For <strong>UTI</strong>: urinary antiseptic; used together with <a href="?herb=46"><strong>Bearberry</strong></a> (Uva ursi); supportive for urinary tract infections in pregnancy. For <strong>respiratory</strong>: bronchitis — antimicrobial, antispasmodic, expectorant, anti-inflammatory, anti-catarrhal, and diaphoretic (if fever); indicated for hot and damp lung. For <strong>wounds</strong>: antimicrobial and antifungal applied externally to cuts and infected wounds. Tip: heat up tincture to improve activity for hot/damp infections. Contrast with <a href="?herb=33"><strong>Oregon Grape Root</strong></a> (digestive system affinity).$$
WHERE id = 112;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Valerian</strong> is a <strong>sedative</strong>, <strong>analgesic</strong>, <strong>antispasmodic</strong>, and <strong>nervine</strong> herb — a strong palliative sedative ("knocker outer") that acts on <strong>GABA</strong> to calm neuronal firing and promote sleep and relaxation. For <strong>sleep</strong>: GABA support; promotes deep sleep; time herbs between 5–7 PM; hypnotic analgesic that decreases pain and increases sleep quality — "won't sedate an unwilling person"; for pain-induced insomnia; with hops for sleep encouragement. For <strong>pain and spasm</strong>: mild pain reliever; antispasmodic for both smooth and skeletal muscles; sedative/anodyne for bone aches in flu. Sleep formula: 2P Valerian, 1P <a href="?herb=128"><strong>California Poppy</strong></a>, 1/2P <a href="?herb=1652"><strong>Hawthorn</strong></a> leaf and flower, 1/2P <a href="?herb=13"><strong>Holy Basil</strong></a> (Tulsi), 1/2P <a href="?herb=45"><strong>Marshmallow</strong></a>, 1/2P <a href="?herb=167"><strong>Cinnamon</strong></a>. <strong>Cautions</strong>: paradoxical stimulant reaction in approximately 10% of people — try a drop dose first; can cause heart palpitations in dry people — pair with <a href="?herb=128"><strong>California Poppy</strong></a> to mitigate. <strong>Preparation</strong>: alkaloidal plant — needs 5–10% vinegar when tincturing; fresh and dried tinctures differ significantly.$$
WHERE id = 145;

UPDATE herbal.herbs
SET class_notes_synopsis = $$<strong>Velvet Bean</strong> (Mucuna pruriens) is a <strong>dopamine-boosting</strong> herb indicated for low motivation, poor concentration, reduced pleasure, fatigue, and difficulty initiating tasks.$$
WHERE id = 2575;
